import {sample,milestones,duration} from './upshift.mjs';
const $=id=>document.getElementById(id),en=new URLSearchParams(location.search).get('lang')==='en',t=(s,e)=>en?e:s,l=en?'en':'es';
document.documentElement.lang=l;document.title=t('Primera → segunda','First → second')+' · Mecánica Lab';
const phases=[
 ['Primera transmite','First gear drives','El primario gira a 900 rpm. Primera reduce 3:1 y mantiene la salida a 300 rpm. Al pisar el embrague, el volante y el disco se separan.','Input speed is 900 rpm. First gear reduces it 3:1 to 300 rpm at the output. Pressing the clutch separates flywheel and disc.','Embrague','Clutch'],
 ['Pasar por neutro','Pass through neutral','El manguito abandona primera y se acerca al cono de segunda. El motor queda separado; la salida sigue rodando.','The sleeve leaves first and approaches the second-gear cone. The engine is disconnected; the output coasts.','Manguito 1–2','1–2 sleeve'],
 ['Fricción en el cono','Cone friction','La rueda libre de segunda gira más rápido que el cubo. El anillo frena esa rueda y, a través de la pareja engranada, también el primario. Mira cómo cae Δrpm.','The free second gear spins faster than the hub. Ring friction slows this wheel and, through its meshing pair, the input shaft. Watch the rpm gap fall.','Cono de segunda','Second-gear cone'],
 ['Igualadas, aún sin bloquear','Matched, not yet locked','Rueda y cubo ya giran juntos a 300 rpm. Solo ahora puede el manguito completar su recorrido hasta los dientes de acoplamiento.','Wheel and hub now both spin at 300 rpm. Only now can the sleeve complete its travel into the dog teeth.','Δ = 0 rpm','Δ = 0 rpm'],
 ['Segunda bloqueada','Second gear locked','El manguito une la rueda al cubo. El embrague sigue abierto: que la marcha esté puesta aún no significa que el motor entregue par.','The sleeve locks the wheel to the hub. The clutch is still open: engaging the gear alone does not restore engine torque.','Manguito acoplado','Engaged sleeve'],
 ['Volver a embragar','Re-engage clutch','El motor se aproxima a 500 rpm al soltar el acelerador. El plato vuelve a apretar el disco cuando el motor y el primario coinciden en este ejemplo.','With the throttle released the engine approaches 500 rpm. In this example the plate clamps the disc as engine and input speeds match.','Disco de embrague','Clutch disc'],
 ['Segunda transmite','Second gear drives','El motor y el primario giran a 500 rpm. Segunda entrega 500 × 18/30 = 300 rpm a la salida: la misma velocidad del vehículo con menos rpm de motor.','Engine and input turn at 500 rpm. Second delivers 500 × 18/30 = 300 rpm at the output: the same vehicle speed at lower engine rpm.','Brida de salida','Output flange']
];
const text=(id,value)=>$(id).textContent=value;
text('heading',t('De primera a segunda','From first to second'));text('eyebrow',t('Caja de cambios / cámara lenta','Transmission / slow motion'));text('intro',t('Sigue el manguito y compara la rueda libre de segunda con el cubo de salida. Arrastra el cursor para inspeccionar el instante de acople.','Follow the sleeve and compare the free second gear with the output hub. Scrub to inspect the moment of engagement.'));
text('back',t('← Caja de cambios','← Gearbox'));$('back').href='lab.html?stage=5&lang='+l;text('lang',en?'ES':'EN');$('lang').href='?lang='+(en?'es':'en');text('rateLabel',t('Reproducción','Playback'));text('scrub',t('Instante del cambio','Shift time'));text('prev',t('← Fase anterior','← Previous phase'));text('next',t('Siguiente fase →','Next phase →'));text('note',t('Magnitudes de rpm. La salida y su rueda giran en sentido contrario al primario. Modelo didáctico: salida constante por inercia y frenado lineal prescrito, sin cálculo de fuerzas de fricción.','RPM magnitudes. Output and driven wheel rotate opposite the input. Teaching model: constant coasting output and prescribed linear deceleration, without a friction-force calculation.'));
const labels=[t('Motor','Engine'),t('Primario','Input shaft'),t('Salida / cubo','Output / hub'),t('Rueda libre de 2.ª','Free second gear')];const meters=labels.map(label=>{const row=document.createElement('div'),title=document.createElement('span'),rpm=document.createElement('b'),bar=document.createElement('meter');title.textContent=label;bar.min=0;bar.max=900;bar.setAttribute('aria-label',label+' rpm');row.append(title,rpm,bar);$('meters').append(row);return [rpm,bar]});
let time=0,playing=false,rate=.125,last=null,rig=null,phase=-1;
function render(){const f=sample(time),values=[f.engine.rpm,f.input.rpm,Math.abs(f.output),Math.abs(f.second)];meters.forEach(([n,b],i)=>{const s=Math.round(values[i])+' rpm';if(n.textContent!==s)n.textContent=s;b.value=values[i]});
 text('gap','Δ '+t('rueda − cubo','wheel − hub')+': '+f.delta.toFixed(1)+' rpm');text('clock',time.toFixed(2)+' / 3.20 s');$('cursor').value=Math.round(time*1000);text('play',playing?t('Ⅱ Pausar','Ⅱ Pause'):time>=duration?t('↺ Repetir','↺ Replay'):t('▷ Reproducir','▷ Play'));$('prev').disabled=time===0;$('next').disabled=f.phase===phases.length-1;
 if(phase!==f.phase){phase=f.phase;const item=phases[phase];text('phase',t('Fase ','Phase ')+(phase+1)+' / 7');text('name',item[+en]);text('why',item[2+(+en)]);rig?.label(item[4+(+en)])}
 rig?.draw(0,f)}
function seek(n){playing=false;last=null;time=n;render()}
$('cursor').oninput=()=>seek(+$('cursor').value/1000);$('next').onclick=()=>seek(milestones[Math.min(phase+1,6)]);$('prev').onclick=()=>seek(milestones[Math.max(0,time>milestones[phase]+.01?phase:phase-1)]);$('play').onclick=()=>{if(time>=duration)time=0;playing=!playing;last=null;render()};$('rate').onchange=()=>rate=+$('rate').value;
render();
try{rig=(await import('./model.mjs')).bench($('stage'));rig.setup(5,2,{step:1});phase=-1;render()}catch{ text('stage',t('WebGL no disponible. El cursor y los tacómetros siguen activos.','WebGL unavailable. Timeline and tachometers remain active.'))}
document.addEventListener('visibilitychange',()=>last=null);
function frame(now){if(!document.hidden){if(playing&&last!==null){time=Math.min(duration,time+(now-last)*.001*rate);if(time===duration)playing=false}if(playing||last===null||time===duration)render();else rig?.draw(0,sample(time));last=now}requestAnimationFrame(frame)}requestAnimationFrame(frame);

$('compare').href='synchro.html?lang='+l;text('compare',t('Comparar sano y desgastado →','Compare healthy and worn →'));
